type Service = ReturnType<typeof createService>;
type Nav = WorkflowView;
const navigation: { id: Nav; name: string; icon: typeof Clock3 }[] = [{ id: 'overview', name: 'Übersicht', icon: LayoutDashboard }, { id: 'projects', name: 'Projekte', icon: FolderKanban }, { id: 'tasks', name: 'Aufgaben', icon: ListTodo }, { id: 'time', name: 'Zeiten', icon: Clock3 }, { id: 'reports', name: 'Auswertung', icon: BarChart3 }, { id: 'team', name: 'Team', icon: Users }, { id: 'finance', name: 'Finance', icon: BarChart3 }, { id: 'settings', name: 'Einstellungen', icon: Settings2 }];
// On phones the bottom bar keeps the four everyday areas; these open from the "More" sheet instead.
const mobileSecondary: Nav[] = ['reports', 'team', 'finance', 'settings'];
type Dataset = { projects: Project[]; tasks: Task[]; members: Membership[]; entries: TimeEntry[]; timer: RunningTimer | null; demo: DemoWorkspace | null; queue: { count: number; oldest: string | null }; inbox: AppNotification[] };
type Modal = { type: 'project'; item?: Project } | { type: 'task'; item?: Task; projectId?: string } | { type: 'entry'; item?: TimeEntry; projectId?: string } | { type: 'invite' } | { type: 'confirm'; title: string; text: string | ((locale: Locale) => string); label: string; action: () => Promise<unknown> };
function Status({ value }: { value: keyof typeof statusNames }) {
  const { t } = useI18n(); return <span className={`badge badge-${value}`}>{t(statusNames[value])}</span>; }
function ProjectMark({ project }: { project?: Project }) {
  return <span className="project-mark" style={{ backgroundColor: project?.color || '#641dff' }} aria-hidden="true">{project?.code.slice(0, 2) || '↗'}</span>; }
function sum(entries: TimeEntry[]) { return entries.reduce((n, entry) => n + entry.minutes, 0); }

export function WorkspaceApp({ client, session, config, signOut }: { client: SupabaseClient; session: Session; config: RuntimeConfig; signOut: () => Promise<void> }) {
  const { t, locale } = useI18n();
  const service = useMemo(() => createService(client), [client]); const demoService = useMemo(() => createDemoService(client), [client]); const [workspaces, setWorkspaces] = useState<Workspace[]>([]); const [selected, setSelected] = useState<string|null>(''); const [ready, setReady] = useState(false); const [error, setError] = useState(''); const [creating, setCreating] = useState(false); const [attempt, setAttempt] = useState(0);
  useEffect(() => { let alive = true; setReady(false); setError(''); (async () => { try { await service.acceptInvitations(); const list = await service.listWorkspaces(); if (!alive) return; setWorkspaces(list); setSelected(resolveWorkflowWorkspace(window.location.hash,list.map(w=>w.id))); } catch (e) { if (alive) setError(errorMessage(e)); } finally { if (alive) setReady(true); } })(); return () => { alive = false; }; }, [service, attempt]);
  useEffect(()=>{
    const restore=()=>setSelected(resolveWorkflowWorkspace(window.location.hash,workspaces.map(w=>w.id)));
    window.addEventListener('popstate',restore);window.addEventListener('hashchange',restore);
    return()=>{window.removeEventListener('popstate',restore);window.removeEventListener('hashchange',restore);};
  },[workspaces]);
  const selectWorkspace=(id:string)=>{
    const hash=id?workflowHash(initialWorkflow(id)):'';
    if(window.location.hash!==hash)window.history.pushState(null,'',window.location.pathname+window.location.search+hash);
    setSelected(id);setCreating(false);
  };
  const adminService=useMemo(()=>createWorkspaceAdminService(client),[client]);
  const [managing,setManaging]=useState(false);const [ownedIds,setOwnedIds]=useState<string[]>([]);
  useEffect(()=>{if(!ready)return;let alive=true;void adminService.listOwned().then(list=>{if(alive)setOwnedIds(list.map(w=>w.id));}).catch(()=>{});return()=>{alive=false;};},[adminService,workspaces,ready]);
  const workspace = workspaces.find(w => w.id === selected);
  const deleted=(id:string)=>{
    const remaining=workspaces.filter(w=>w.id!==id);setWorkspaces(remaining);setOwnedIds(ids=>ids.filter(value=>value!==id));
    if(selected===id){const next=remaining[0]?.id??'';const hash=next?workflowHash(initialWorkflow(next)):'';window.history.replaceState(null,'',window.location.pathname+window.location.search+hash);setSelected(next);setCreating(false);}
  };
  const management=managing&&<WorkspaceAdminDialog key="workspace-admin" service={adminService} currentId={workspace?.id} onClose={()=>setManaging(false)} onDeleted={deleted}/>;
  const manageEntry=<button className="button secondary workspace-admin-entry" type="button" onClick={()=>setManaging(true)}>{workspaceAdminText(locale,'title')}</button>;
  const created = (w: Workspace) => { setWorkspaces(old => [...old, w]); selectWorkspace(w.id); };
  if (!ready) return <div className="boot"><Spinner label={t('Deine Workspaces werden geladen …')}/></div>;
  if (error) return <AuthShell><section className="auth-card"><h2>{t('Fast da.')}</h2><Notice>{error}</Notice><button className="button primary" onClick={() => setAttempt(n => n + 1)}><RefreshCw size={17}/> {t('Erneut versuchen')}</button><button className="text-button block" onClick={() => void signOut()}>{t('Abmelden')}</button></section></AuthShell>;
  if (selected===null) return <><AuthShell><section className="auth-card"><h2>{wt(locale,'workspaceUnavailable')}</h2><p>{wt(locale,'workspaceUnavailableHint')}</p><button className="button primary" onClick={()=>selectWorkspace(workspaces[0]?.id??'')}>{wt(locale,'openWorkspace')}</button>{manageEntry}</section></AuthShell>{management}</>;
  if (!workspace) return <><AuthShell caption={t('Ein Team. Ein gemeinsamer Flow.')}><WorkspaceForm demoService={demoService} service={service} onCreated={created} onCancel={() => void signOut()} first onManageWorkspaces={()=>setManaging(true)}/></AuthShell>{management}</>;
  return <><WorkspaceView onManageWorkspaces={()=>setManaging(true)} hasOwnedWorkspaces={ownedIds.length>0} key={`${session.user.id}:${workspace.id}`} demoService={demoService} onArchived={(id) => { setWorkspaces(old => old.filter(w => w.id !== id)); selectWorkspace(workspaces.find(w => w.id !== id)?.id || ''); }} service={service} client={client} session={session} workspace={workspace} workspaces={workspaces} onWorkspace={selectWorkspace} onCreateWorkspace={() => setCreating(true)} config={config} signOut={signOut}/>{creating && <Dialog title={t('Neuer Workspace')} onClose={() => setCreating(false)}><WorkspaceForm demoService={demoService} service={service} onCreated={created} onCancel={() => setCreating(false)}/></Dialog>}{management}</>;
}
function WorkspaceForm({ service, demoService, onCreated, onCancel, first = false, onManageWorkspaces }: { service: Service; demoService: DemoService; onManageWorkspaces?:()=>void; onCreated: (w: Workspace) => void; onCancel: () => void; first?: boolean }) {
  const { t, locale } = useI18n();
  const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [start, setStart] = useState<WorkspaceStart>('empty'); const [workspaceName, setWorkspaceName] = useState(''); const [requestId] = useState(() => crypto.randomUUID());
  const defaultZone = new Intl.DateTimeFormat().resolvedOptions().timeZone || 'Europe/Berlin';
  // Every IANA zone the browser supports, grouped by region; validated again on submit.
  const timezoneOptions = useMemo(() => {
    const supported = (Intl as { supportedValuesOf?: (key: 'timeZone') => string[] }).supportedValuesOf;
    const zones = new Set<string>(['UTC', defaultZone, 'Europe/Berlin', 'Europe/Vienna', 'Europe/Zurich', 'Europe/London', 'America/New_York', 'America/Los_Angeles', 'Asia/Tokyo', 'Asia/Shanghai', 'Asia/Singapore', 'Asia/Dubai']);
    try { for (const zone of supported?.call(Intl, 'timeZone') ?? []) zones.add(zone); } catch { /* The curated fallback list remains available. */ }
    return [...zones].sort().map(zone => ({ value: zone, label: zone.replaceAll('_', ' '), group: zone.includes('/') ? zone.split('/')[0] : 'UTC' }));
  }, [defaultZone]);
  // oxlint-disable-next-line no-new -- Intl-Konstruktor dient als Zeitzonen-Validierung (wirft bei ungültiger Zone).
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); setBusy(true); setError(''); const f = new FormData(e.currentTarget); try { const timezone = String(f.get('timezone')).trim(); try { new Intl.DateTimeFormat(locale, { timeZone: timezone }); } catch { throw new Error(t('Bitte gib eine gültige IANA-Zeitzone ein, zum Beispiel Europe/Berlin.')); } const name = String(f.get('name')).trim(); const w = start === 'demo' ? await demoService.create({ name, timezone, locale, requestId }) : await service.createWorkspace({ name, timezone, currency: String(f.get('currency')).toUpperCase() }); onCreated(w); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); } }
  return <section className={first ? 'auth-card' : ''}>{first && <><p className="eyebrow purple">{t('DEIN ERSTER WORKSPACE')}</p><h2>{t('Hier beginnt')}<br/>{t('euer nächstes Projekt.')}</h2><p className="muted">{t('Gib eurem gemeinsamen Arbeitsort einen Namen. Projekte und Team kommen gleich dazu.')}</p></>}{error && <Notice>{error}</Notice>}<form className="form-stack" onSubmit={submit}><DemoChoice value={start} disabled={busy} onChange={value => { setStart(value); if (value === 'demo' && !workspaceName) setWorkspaceName('VAVE · Demo'); }}/><Field label={t('Workspace-Name')}><input name="name" value={workspaceName} onChange={event => setWorkspaceName(event.target.value)} required minLength={1} maxLength={100} placeholder={t('Zum Beispiel: Studio Nord')} autoComplete="organization"/></Field><Field label={t('Zeitzone')} hint={t('Timer werden an Mitternacht in dieser Zeitzone aufgeteilt.')}><SelectMenu name="timezone" required label={t('Zeitzone')} defaultValue={defaultZone} options={timezoneOptions} searchable searchPlaceholder={t('Zeitzone suchen …')}/></Field><Field label={t('Währung')}><SelectMenu name="currency" label={t('Währung')} defaultValue="EUR" disabled={start === 'demo'} options={[{ value: 'EUR', label: t('EUR · Euro') }, { value: 'CHF', label: t('CHF · Schweizer Franken') }, { value: 'USD', label: t('USD · US-Dollar') }, { value: 'GBP', label: t('GBP · Pfund Sterling') }, { value: 'CNY', label: 'CNY' }, { value: 'HKD', label: 'HKD' }, { value: 'JPY', label: 'JPY' }, { value: 'SGD', label: 'SGD' }, { value: 'AED', label: 'AED' }]}/></Field>{first ? <><button className="button primary full" disabled={busy}>{busy ? t('Wird angelegt …') : t('Workspace anlegen')}<ArrowRight size={17}/></button><button className="text-button" disabled={busy} type="button" onClick={onCancel}>{t('Abmelden')}</button><p className="tiny muted">{t('Du wurdest eingeladen? Melde dich mit der eingeladenen, bestätigten E-Mail-Adresse an. Einladungen werden beim Anmelden automatisch angenommen.')}</p></> : <FormActions busy={busy} onClose={onCancel} label={t('Workspace anlegen')}/>}</form>{first&&onManageWorkspaces&&<button className="button secondary full workspace-admin-entry" type="button" disabled={busy} onClick={onManageWorkspaces}>{workspaceAdminText(locale,'title')}</button>}</section>;
}

function WorkspaceView({ onManageWorkspaces, hasOwnedWorkspaces, service, demoService, onArchived, client, session, workspace, workspaces, onWorkspace, onCreateWorkspace, config, signOut }: { onManageWorkspaces:()=>void; hasOwnedWorkspaces:boolean; service: Service; demoService: DemoService; onArchived: (id: string) => void; client: SupabaseClient; session: Session; workspace: Workspace; workspaces: Workspace[]; onWorkspace: (id: string) => void; onCreateWorkspace: () => void; config: RuntimeConfig; signOut: () => Promise<void> }) {
  const { t, locale } = useI18n();
  const {route,navigate,revision}=useWorkflowNavigation(workspace.id); const nav=route.view; const [insightId,setInsightId]=useState(''); const [range, setRange] = useState(() => weekFor(dateInZone(workspace.timezone))); const [data, setData] = useState<Dataset | null>(null); const [loadedRange, setLoadedRange] = useState(''); const [loading, setLoading] = useState(true); const [loadError, setLoadError] = useState(''); const [notice, setNotice] = useState<{ message: string; error: boolean } | null>(null); const [busy, setBusy] = useState(false); const [modal, setModal] = useState<Modal | null>(null); const generation = useRef(0); const mounted = useRef(true);
  // oxlint-disable-next-line react-hooks/exhaustive-deps -- Mounted-Flag: .current im Cleanup ist hier der Zweck des Refs.
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; generation.current++; }; }, []);
  const [moreOpen, setMoreOpen] = useState(false);
  useEffect(() => { setMoreOpen(false); }, [nav]);
  useEffect(() => { if (!moreOpen) return; const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') setMoreOpen(false); }; window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey); }, [moreOpen]);
  const load = useCallback(async () => { const request = ++generation.current; setLoading(true); setLoadError(''); try { const [projects, tasks, members, entries, timer, demo, queue, inbox] = await Promise.all([service.listProjects(workspace.id), service.listTasks(workspace.id), service.getMemberships(workspace.id), service.listEntries(workspace.id, range.from, range.to), service.getTimer(), demoService.get(workspace.id), service.approvalQueue(workspace.id), service.listNotifications(workspace.id)]); if (mounted.current && request === generation.current) { setData({ projects, tasks, members, entries, timer, demo, queue, inbox }); setLoadedRange(`${range.from}:${range.to}`); } } catch (e) { if (mounted.current && request === generation.current) { setData(null); setLoadError(errorMessage(e)); } } finally { if (mounted.current && request === generation.current) setLoading(false); } }, [service, demoService, workspace.id, range.from, range.to]);
  useEffect(() => { void load(); }, [load]);
  // Returning to this tab refreshes server-owned timers and membership changes.
  useEffect(() => { const onVisible = () => { if (document.visibilityState === 'visible') void load(); }; document.addEventListener('visibilitychange', onVisible); return () => document.removeEventListener('visibilitychange', onVisible); }, [load]);
  const self = data?.members.find(m => !m.is_demo && m.user_id === session.user.id); const role = self?.role ?? 'member'; const manager = role === 'owner' || role === 'manager'; const name = self?.display_name || session.user.email?.split('@')[0] || t('du');
  useEffect(() => { if(data && !manager){setInsightId('');if(nav === 'team' || nav === 'finance')navigate({view:'overview',projectId:''},true);} }, [manager, nav, data, navigate]);
  async function run(action: () => Promise<unknown>, success?: string) { if (busy) return false; setBusy(true); setNotice(null); try { await action(); if (!mounted.current) return true; setModal(null); await load(); if (mounted.current && success) setNotice({ message: success, error: false }); return true; } catch (e) { if (mounted.current) setNotice({ message: errorMessage(e), error: true }); return false; } finally { if (mounted.current) setBusy(false); } }
  function go(next: Nav, context: Omit<WorkflowTarget,'view'> = {}) { navigate({view:next,...context,...(['overview','team','settings'].includes(next)?{projectId:''}:{})}); setInsightId(''); setModal(null); setNotice(null); document.getElementById('main-title')?.focus(); }
  const openWorkflow=(target:WorkflowTarget)=>go(target.view,{...target,...(target.view==='time'&&target.projectId&&target.timeScope===undefined?{timeScope:manager?'team' as const:'own' as const,entryStatus:'all' as const}:{}),taskFilters:target.taskFilters??emptyTaskFilters()});
  const scopedProject=data?.projects.find(p=>p.id===route.projectId&&p.workspace_id===workspace.id);
  const missingProject=Boolean(data&&route.projectId&&!scopedProject);
  const newItem=(type:'task'|'entry',projectId=route.projectId)=>setModal({type,projectId:projectId||undefined});
  const titles: Record<Nav, { title: string; subtitle: string }> = { overview: { title: t('Guten Flow, {name}.', { name: name.split(' ')[0] }), subtitle: t('Ein klarer Blick auf deine Arbeit.') }, projects: { title: t('Raum für gute Projekte.'), subtitle: t('Vom ersten Gedanken bis zum letzten Feinschliff.') }, tasks: { title: t('Ein Schritt nach dem anderen.'), subtitle: t('Was ansteht. Was läuft. Was geschafft ist.') }, time: { title: t('Deine Zeit zählt.'), subtitle: t('Erfassen, prüfen und mit gutem Gefühl einreichen.') }, reports: { title: t('Der Überblick fürs Ganze.'), subtitle: t('Arbeitszeit und Projektbudgets im gewählten Zeitraum.') }, team: { title: t('Gemeinsam kommt ihr weiter.'), subtitle: t('Menschen, Rollen und euer gemeinsamer Workspace.') }, finance: { title: agencyText(locale,'financeTitle'), subtitle: agencyText(locale,'financeSubtitle') }, settings: { title: t('Alles gut eingestellt.'), subtitle: t('Dein Account, dein Workspace und deine Verbindungen.') } };
  const visibleNavigation = navigation.filter(item => (item.id !== 'team' && item.id !== 'finance') || manager);
  const navButton = (item: typeof navigation[number], extra = '') => <button key={item.id} type="button" className={`nav-item ${extra} ${nav === item.id ? 'active' : ''}`} onClick={() => { setMoreOpen(false); go(item.id); }} aria-current={nav === item.id ? 'page' : undefined}><item.icon size={19}/><span>{item.id === 'finance' ? agencyText(locale,'finance') : t(item.name)}</span>{item.id === 'time' && !!data?.queue.count && manager && <span className="nav-count">{data.queue.count}</span>}</button>;
  return <div className="app-shell"><a className="skip-link" href="#main" onClick={event=>{event.preventDefault();document.getElementById('main')?.focus();}}>{t('Zum Inhalt')}</a><aside className="sidebar"><Logo/><div className="workspace-switch"><label htmlFor="workspace-select">{t('WORKSPACE')}</label><div className="workspace-select-row"><span className="workspace-avatar">{initials(workspace.name)}</span><SelectMenu id="workspace-select" bare label={t('Workspace wechseln')} value={workspace.id} onChange={onWorkspace} options={workspaces.map(w => ({ value: w.id, label: w.name, avatar: initials(w.name) }))} renderValue={selected => <span className="sm-value"><span className="sm-value-label">{selected?.label}</span></span>}/></div><button className="text-button tiny" onClick={onCreateWorkspace}><Plus size={13}/><span>{t('Neuer Workspace')}</span></button></div><nav aria-label={t('Hauptnavigation')} className={moreOpen ? 'sheet-open' : ''}>{visibleNavigation.map(item => navButton(item, mobileSecondary.includes(item.id) ? 'mobile-secondary' : ''))}<button type="button" className={`nav-item nav-more ${mobileSecondary.includes(nav) ? 'active' : ''}`} aria-expanded={moreOpen} onClick={() => setMoreOpen(open => !open)}><MoreHorizontal size={19}/><span>{t('Mehr')}</span></button>{moreOpen && <><div className="nav-sheet-backdrop" aria-hidden="true" onClick={() => setMoreOpen(false)}/><div className="nav-more-sheet" role="group" aria-label={t('Weitere Bereiche')}>{visibleNavigation.filter(item => mobileSecondary.includes(item.id)).map(item => navButton(item))}</div></>}</nav><div className="sidebar-bottom"><div className="small-manifesto">{t('Good work.')}<br/><span>{t('Great flow.')}</span><ArrowUpRight size={27}/></div><div className="profile"><span className="avatar">{initials(name)}</span><div><strong>{name}</strong><small>{t(roleNames[role])}</small></div><button className="icon-button" aria-label={t('Abmelden')} title={t('Abmelden')} onClick={() => void signOut()}><LogOut size={17}/></button></div></div></aside><div className="app-main"><header className="topbar"><span className="breadcrumb">{workspace.name}<span>/</span><strong>{(nav === 'finance' ? agencyText(locale,'finance') : t(navigation.find(n => n.id === nav)?.name ?? ''))}</strong></span><div className="topbar-right"><LanguageSwitcher/><span className="timezone"><span className="status-dot"/>{workspace.timezone}</span><button className="icon-button" aria-label={t('Daten aktualisieren')} disabled={loading || busy} onClick={() => void load()}><RefreshCw size={17} className={loading ? 'spin' : ''}/></button><span className="avatar small-avatar" title={session.user.email}>{initials(name)}</span></div></header><main id="main" tabIndex={-1} className="main-content"><div className="page-heading"><div><p className="eyebrow">{nav === 'overview' ? t('LET’S MAKE IT COUNT') : 'VAVE.LOG / ' + (nav === 'finance' ? agencyText(locale,'finance') : t(navigation.find(n => n.id === nav)?.name ?? '')).toUpperCase()}</p><h1 id="main-title" tabIndex={-1}>{titles[nav].title}</h1><p>{titles[nav].subtitle}</p></div><div className="heading-actions">{(nav === 'overview' || nav === 'time') && <button className="button primary" disabled={!data?.projects.some(p => p.status === 'active') || loading || Boolean(route.projectId && scopedProject?.status!=='active')} onClick={() => newItem('entry')}><Plus size={17}/> {t('Zeit erfassen')}</button>}{nav === 'projects' && manager && <button className="button primary" onClick={() => setModal({ type: 'project' })}><Plus size={17}/> {t('Neues Projekt')}</button>}{nav === 'tasks' && <button className="button primary" disabled={!data?.projects.some(p => p.status === 'active') || loading || Boolean(route.projectId && scopedProject?.status!=='active')} onClick={() => newItem('task')}><Plus size={17}/> {t('Neue Aufgabe')}</button>}{nav === 'team' && role === 'owner' && <button className="button primary" onClick={() => setModal({ type: 'invite' })}><Plus size={17}/> {t('Person einladen')}</button>}</div></div>{notice && <div className="notice-row"><Notice kind={notice.error ? 'error' : 'success'}>{notice.message}</Notice><button className="icon-button" aria-label={t('Hinweis schließen')} onClick={() => setNotice(null)}><X size={16}/></button></div>}{data && data.inbox.length > 0 && (() => { const approved = data.inbox.filter(n => n.kind === 'entries_approved').reduce((s, n) => s + n.entry_count, 0); const returned = data.inbox.filter(n => n.kind === 'entries_returned').reduce((s, n) => s + n.entry_count, 0); return <div className="notice-row"><Notice kind={returned > 0 ? 'info' : 'success'}>{[approved > 0 ? t('{count} deiner Zeiteinträge wurden freigegeben.', { count: approved }) : '', returned > 0 ? t('{count} deiner Zeiteinträge wurden zurück in den Entwurf gegeben – bitte prüfen und erneut einreichen.', { count: returned }) : ''].filter(Boolean).join(' ')}</Notice><button className="button secondary small" onClick={() => { void service.markNotificationsRead(workspace.id).then(() => setData(d => d ? { ...d, inbox: [] } : d)).catch(() => {/* bleibt beim nächsten Laden sichtbar */}); }}>{t('Verstanden')}</button></div>; })()}{scopedProject&&['projects','tasks','time','reports','finance'].includes(nav)&&<div className="workflow-context"><div><span className="color-dot" style={{backgroundColor:scopedProject.color}}/><small>{wt(locale,'context')}</small><button className="project-text-link" onClick={()=>go('projects')}><strong>{scopedProject.code} · {scopedProject.name}</strong></button></div><button className="text-button tiny" onClick={()=>go(nav,{projectId:'',taskFilters:emptyTaskFilters(),personId:'',entryStatus:'all'})}>{wt(locale,'clearProject')}<X size={13}/></button></div>}{['overview','projects','time','reports'].includes(nav) && <RangePicker key={`${range.from}:${range.to}`} range={range} onChange={setRange} today={dateInZone(workspace.timezone)} busy={busy}/>}{loading && (!data || loadedRange !== `${range.from}:${range.to}`) ? <Spinner label={t('Workspace wird aktualisiert …')}/> : loadError ? <div className="panel"><Notice>{loadError}</Notice><button className="button secondary" onClick={() => void load()}>{t('Erneut versuchen')}</button></div> : missingProject ? <section className="panel"><Empty title={wt(locale,'unavailable')} text={wt(locale,'unavailableHint')} action={<button className="button secondary" onClick={()=>go(nav,{projectId:'',taskFilters:emptyTaskFilters()})}>{wt(locale,'clearProject')}</button>}/></section> : data && <>{nav === 'settings' && data.demo && <DemoBanner demo={data.demo} canArchive={role === 'owner' && data.demo.created_by === session.user.id} busy={busy} onUpgrade={() => void run(() => demoService.upgrade(workspace.id), agencyText(locale,'demoCompleted'))} onArchive={() => setModal({type:'confirm',title:agencyText(locale,'archiveTitle'),text:currentLocale => agencyText(currentLocale,'archiveText'),label:agencyText(locale,'archive'),action:async() => { await demoService.archive(workspace.id); onArchived(workspace.id); }})}/>} {nav === 'finance' && manager && <Suspense fallback={<Spinner label={t('Workspace wird aktualisiert …')}/>}><FinanceArea key={`${workspace.id}:${role}:${data.demo?.experience_version??0}`} client={client} workspace={workspace} members={data.members} projects={data.projects} role={role} isDemo={Boolean(data.demo)} navigation={{projectId:route.projectId,tab:route.financeTab,revision}} onNavigate={openWorkflow}/></Suspense>} {nav === 'overview' && <Overview data={data} workspace={workspace} userId={session.user.id} range={range} manager={manager} setModal={setModal} go={go} service={service} run={run} busy={busy} workspaces={workspaces}/>} {nav === 'projects' && <ProjectsArea key={route.projectId} projects={data.projects} tasks={data.tasks} entries={data.entries} projectId={route.projectId} manager={manager} range={range} onCreate={()=>setModal({type:'project'})} onEdit={item=>setModal({type:'project',item})} onTask={id=>newItem('task',id)} onTime={id=>newItem('entry',id)} onNavigate={openWorkflow} onInsight={setInsightId}/>} {nav === 'tasks' && <TasksArea projects={data.projects} tasks={data.tasks} members={data.members} userId={session.user.id} timezone={workspace.timezone} projectId={route.projectId} filters={route.taskFilters} busy={busy} onProject={projectId=>navigate({view:'tasks',projectId})} onFilters={(taskFilters,replace)=>navigate({view:'tasks',taskFilters},replace)} onOpenProject={projectId=>go('projects',{projectId})} onEdit={item=>setModal({type:'task',item})} onMove={(task,status)=>{void run(()=>service.saveTask({id:task.id,workspace_id:task.workspace_id,project_id:task.project_id,title:task.title,status,assignee_id:task.assignee_id,due_date:task.due_date,estimated_minutes:task.estimated_minutes??null,is_milestone:task.is_milestone??false}),t('Aufgabenstatus aktualisiert.'));}}/>} {nav === 'time' && <Times data={data} userId={session.user.id} manager={manager} range={range} workspace={workspace} workspaces={workspaces} setModal={setModal} service={service} run={run} busy={busy} route={route} onNavigate={openWorkflow} onShowQueue={() => { const today = dateInZone(workspace.timezone); const floor = addDays(today, -365); const oldest = data?.queue.oldest ?? today; setRange({ from: oldest < floor ? floor : oldest, to: today }); openWorkflow({ view: 'time', timeScope: manager ? 'team' : 'own', entryStatus: 'submitted' }); }}/>} {nav === 'reports' && <Reports data={data} range={range} manager={manager} route={route} service={service} workspace={workspace} onNavigate={openWorkflow}/>} {nav === 'team' && manager && <Team data={data} userId={session.user.id} role={role} service={service} run={run} busy={busy} workspace={workspace} setModal={setModal} onNavigate={openWorkflow}/>} {nav === 'settings' && <><Settings onManageWorkspaces={onManageWorkspaces} hasOwnedWorkspaces={hasOwnedWorkspaces} workspace={workspace} self={self} client={client} config={config} signOut={signOut}/><Connections tasks={data.tasks} projects={data.projects} manager={manager}/></>}</>}<footer className="app-footer"><span>VAVE.LOG <span className="footer-dot">●</span> {t('SPACE FOR GOOD WORK')}</span><span>{workspace.name}</span></footer></main></div>{data?.timer && <GlobalTimer key={data.timer.id} timer={data.timer} projects={data.projects} workspace={workspace} workspaces={workspaces} floating={nav !== 'overview' && nav !== 'time'} service={service} run={run} busy={busy} onOpen={() => go('overview')}/>}{insightId&&manager&&data&&!loadError&&<ProjectInsightDialog key={`${workspace.id}:${insightId}:${role}`} service={service} workspaceId={workspace.id} projectId={insightId} onClose={()=>setInsightId('')} onEdit={item=>{setInsightId('');setModal({type:'project',item});}} onNavigate={(target,filters)=>openWorkflow({taskFilters:{...emptyTaskFilters(),...filters},view:target==='planning'||target==='invoices'?'finance':target,projectId:insightId,financeTab:target==='planning'||target==='invoices'?target:undefined,timeScope:manager?'team':'own'})}/>} {modal && data && <Editor key={modal.type === 'project' || modal.type === 'task' || modal.type === 'entry' ? `${modal.type}:${modal.item?.id || ('projectId' in modal?modal.projectId:'') || 'new'}` : modal.type} modal={modal} data={data} workspace={workspace} service={service} run={run} busy={busy} onClose={() => setModal(null)} appUrl={config.appUrl} client={client} onNavigate={openWorkflow} errorDetail={notice?.error ? notice.message : undefined}/>}</div>;
}

function RangePicker({ range, onChange, today, busy }: { range: { from: string; to: string }; onChange: (r: { from: string; to: string }) => void; today: string; busy: boolean }) {
  const { t } = useI18n();
  const [from, setFrom] = useState(range.from); const [to, setTo] = useState(range.to); const [expanded, setExpanded] = useState(false); const [error, setError] = useState('');
  const days = Math.round((Date.parse(range.to) - Date.parse(range.from)) / 86400000) + 1;
  return <div className="range-toolbar"><div className="range-controls"><button className="icon-button" aria-label={t('Vorheriger Zeitraum')} disabled={busy} onClick={() => onChange({ from: addDays(range.from, -days), to: addDays(range.to, -days) })}><ChevronLeft size={17}/></button><button className="range-label" aria-expanded={expanded} onClick={() => setExpanded(!expanded)}><CalendarDays size={16}/>{shortDate(range.from)} – {shortDate(range.to)}<span className="muted">{range.to.slice(0, 4)}</span></button><button className="icon-button" aria-label={t('Nächster Zeitraum')} disabled={busy} onClick={() => onChange({ from: addDays(range.from, days), to: addDays(range.to, days) })}><ChevronRight size={17}/></button><button className="text-button tiny" disabled={busy} onClick={() => onChange(weekFor(today))}>{t('Diese Woche')}</button></div><span className="range-hint">{t('Alle Auswertungen beziehen sich auf diesen Zeitraum.')}</span>{expanded && <form className="range-form" onSubmit={e => { e.preventDefault(); if (!validRange(from, to)) { setError(t('Wähle einen gültigen Zeitraum von maximal 366 Tagen.')); return; } onChange({ from, to }); setExpanded(false); }}><Field label={t('Von')}><input type="date" min="2000-01-01" max="2100-12-31" required value={from} onChange={e => setFrom(e.target.value)}/></Field><Field label={t('Bis')}><input type="date" min="2000-01-01" max="2100-12-31" required value={to} onChange={e => setTo(e.target.value)}/></Field><button className="button primary small" disabled={busy}>{t('Anwenden')}</button>{error && <Notice>{error}</Notice>}</form>}</div>;
}

type Run = (action: () => Promise<unknown>, success?: string) => Promise<boolean>;
function Overview({ data, workspace, userId, range, manager, setModal, go, service, run, busy, workspaces }: { data: Dataset; workspace: Workspace; userId: string; range: { from: string; to: string }; manager: boolean; setModal: (m: Modal) => void; go: (n: Nav,context?:Omit<WorkflowTarget,'view'>) => void; service: Service; run: Run; busy: boolean; workspaces: Workspace[] }) {
  const { t, locale } = useI18n();
  const own = data.entries.filter(e => e.user_id === userId); const total = sum(own); const billable = sum(own.filter(e => e.billable)); const open = data.tasks.filter(t => t.status !== 'done' && t.assignee_id === userId); const drafts = own.filter(e => e.status === 'draft'); const days = Math.round((Date.parse(range.to) - Date.parse(range.from)) / 86400000) + 1; const bucketSize = Math.ceil(days / 7); const bars = Array.from({ length: Math.ceil(days / bucketSize) }, (_, i) => { const date = addDays(range.from, i * bucketSize); const end = addDays(date, bucketSize - 1); return { date, value: sum(own.filter(e => e.work_date >= date && e.work_date <= end)) }; }); const max = Math.max(60, ...bars.map(b => b.value));
  return <><div className="metric-grid"><Metric label={t('Deine erfasste Zeit')} value={minutesLabel(total)} sub={t('{count} Zeiteinträge im Zeitraum', { count: own.length })} icon={<Clock3 size={19}/>} featured/><Metric label={t('Davon abrechenbar')} value={minutesLabel(billable)} sub={total ? t('{percent} % deiner erfassten Zeit', { percent: Math.round(billable / total * 100) }) : t('Bereit für dein erstes Projekt')} icon={<Activity size={19}/>}/><Metric onClick={()=>go('time',{timeScope:'own',entryStatus:'draft'})} label={t('Bereit zum Einreichen')} value={minutesLabel(sum(drafts))} sub={t('{count} offene Entwürfe', { count: drafts.length })} icon={<CheckCheck size={19}/>}/><Metric onClick={()=>go('tasks',{taskFilters:{...emptyTaskFilters(),quick:'mine'}})} label={t('Deine offenen Aufgaben')} value={String(open.length).padStart(2, '0')} sub={t('Über alle Projekte hinweg')} icon={<ListTodo size={19}/>}/></div><div className="overview-grid"><section className="panel time-chart"><div className="panel-heading"><div><p className="eyebrow">{t('DEIN RHYTHMUS')}</p><h2>{t('Zeit, die etwas bewegt.')}</h2></div><span className="tiny muted">{bucketSize === 1 ? t('Pro Tag') : t('Je {count} Tage', { count: bucketSize })}</span></div><div className="chart" role="img" aria-label={bars.map(b => `${longDate(b.date)}: ${minutesLabel(b.value)}`).join('; ')}>{bars.map(b => <div className="chart-column" key={b.date}><strong>{b.value ? minutesLabel(b.value).replace(' h','') : '–'}</strong><div className="chart-bar-track"><div className={`chart-bar ${b.date === dateInZone(workspace.timezone) ? 'today' : ''}`} style={{ height: `${Math.max(b.value ? 3 : 0, b.value / max * 100)}%` }}/></div><span>{bucketSize === 1 ? new Intl.DateTimeFormat(locale, { weekday: 'short', timeZone: 'UTC' }).format(new Date(`${b.date}T12:00:00Z`)) : shortDate(b.date)}</span></div>)}</div><div className="chart-footer"><span><span className="chart-key"/> {t('Deine erfasste Arbeitszeit')}</span><button className="text-button tiny" onClick={() => go('time')}>{t('Alle Zeiten')} <ArrowRight size={14}/></button></div></section><TimerPanel data={data} workspace={workspace} workspaces={workspaces} service={service} run={run} busy={busy} setModal={setModal}/><section className="panel"><div className="panel-heading"><div><p className="eyebrow">{t('ZULETZT ERFASST')}</p><h2>{t('Deine Arbeit im Rückblick.')}</h2></div><button className="icon-button" aria-label={t('Alle Zeiten öffnen')} onClick={() => go('time')}><ArrowUpRight size={20}/></button></div>{own.length === 0 ? <Empty title={t('Noch ganz viel möglich.')} text={t('Starte den Timer oder erfasse deine erste Arbeitszeit.')} action={<button className="text-button" disabled={!data.projects.some(p => p.status === 'active')} onClick={() => setModal({ type: 'entry' })}>{t('Zeit erfassen')} <ArrowRight size={15}/></button>}/> : <div className="recent-entries">{[...own].sort((a,b) => b.work_date.localeCompare(a.work_date) || b.created_at.localeCompare(a.created_at)).slice(0,4).map(entry => { const p = data.projects.find(p => p.id === entry.project_id); return <div className="recent-entry" key={entry.id}><ProjectMark project={p}/><div className="entry-info"><strong>{entry.note || p?.name || t('Arbeitszeit')}</strong><small><button className="project-text-link" onClick={()=>go('projects',{projectId:entry.project_id})}>{p?.name}<ArrowUpRight size={11}/></button> <span>·</span> {shortDate(entry.work_date)}</small></div><div className="entry-end"><strong>{minutesLabel(entry.minutes)}</strong><Status value={entry.status}/></div></div>; })}</div>}</section><section className="panel next-tasks"><div className="panel-heading"><div><p className="eyebrow">{t('DEIN NÄCHSTER SCHRITT')}</p><h2>{t('Was steht an?')}</h2></div><span className="count-circle">{open.length}</span></div>{open.length === 0 ? <Empty title={t('Freier Kopf. Freie Bahn.')} text={t('Dir sind gerade keine offenen Aufgaben zugewiesen.')} action={<button className="text-button" onClick={() => go('tasks')}>{t('Zum Aufgabenboard')} <ArrowRight size={15}/></button>}/> : open.slice().sort((a,b) => (a.due_date || '9999').localeCompare(b.due_date || '9999')).slice(0,4).map(task => <button className="next-task" key={task.id} onClick={() => setModal({ type: 'task', item: task })}><span className="task-check"/><div><strong>{task.title}</strong><small>{data.projects.find(p => p.id === task.project_id)?.name}</small></div>{task.due_date && <span className={`due-date ${task.due_date < dateInZone(workspace.timezone) ? 'overdue' : ''}`}>{shortDate(task.due_date)}</span>}</button>)}</section></div>{data.projects.length === 0 && <div className="start-strip"><div><strong>{t('Alles beginnt mit einem Projekt.')}</strong><p>{manager ? t('Lege dein erstes Projekt an. Danach könnt ihr Aufgaben und Zeiten hinzufügen.') : t('Bitte die Workspace-Leitung, ein erstes Projekt anzulegen.')}</p></div>{manager && <button className="button secondary" onClick={() => setModal({ type: 'project' })}>{t('Projekt anlegen')} <ArrowUpRight size={17}/></button>}</div>}</>;
}
function Metric({ label, value, sub, icon, featured, onClick }: { label: string; value: string; sub: string; icon: ReactNode; featured?: boolean; onClick?:()=>void }) {
  return <section className={`metric ${featured ? 'featured' : ''}`}><div><span>{label}</span>{icon}</div><strong className="metric-value">{onClick?<button className="metric-link" onClick={onClick} aria-label={label}>{value}<ArrowUpRight size={15}/></button>:value}</strong><p>{sub}</p></section>; }
function useTimerClock(timer: RunningTimer | null) {
  // oxlint-disable-next-line react/purity -- Startwert der Uhr; bewusst einmalig beim Mount gelesen.
  const [now, setNow] = useState(Date.now());
  useEffect(() => { if (!timer) return; const interval = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(interval); }, [timer]);
  const elapsed = timer ? Math.max(0, Math.floor((now - Date.parse(timer.started_at)) / 1000)) : 0;
  return { elapsed, clock: `${String(Math.floor(elapsed / 3600)).padStart(2,'0')}:${String(Math.floor(elapsed / 60) % 60).padStart(2,'0')}:${String(elapsed % 60).padStart(2,'0')}` };
}
const timerWidgetKey = 'vave-log.timer-widget';
// The running timer follows you everywhere: mirrored into the tab/window title
// and, outside the overview, shown as a floating card that minimizes to a pill.
function GlobalTimer({ timer, projects, workspace, workspaces, floating, service, run, busy, onOpen }: { timer: RunningTimer; projects: Project[]; workspace: Workspace; workspaces: Workspace[]; floating: boolean; service: Service; run: Run; busy: boolean; onOpen: () => void }) {
  const { t } = useI18n();
  const { elapsed, clock } = useTimerClock(timer);
  useEffect(() => { document.title = `\u25B6 ${clock} \u00B7 VAVE.LOG`; }, [clock]);
  useEffect(() => () => { document.title = 'VAVE.LOG'; }, []);
  const [mode, setMode] = useState<'open' | 'mini'>(() => { try { return localStorage.getItem(timerWidgetKey) === 'mini' ? 'mini' : 'open'; } catch { return 'open'; } });
  const remember = (next: 'open' | 'mini') => { setMode(next); try { localStorage.setItem(timerWidgetKey, next); } catch { /* The widget still toggles without storage. */ } };
  // On phones the widget docks above the bottom bar; these classes give the page matching clearance.
  useEffect(() => { if (!floating) return; document.body.classList.add('timer-floating'); document.body.classList.toggle('timer-open', mode === 'open'); return () => document.body.classList.remove('timer-floating', 'timer-open'); }, [floating, mode]);
  if (!floating) return null;
  if (mode === 'mini') return <button type="button" className="floating-timer-mini" onClick={() => remember('open')} aria-label={t('Timer anzeigen: {time}', { time: clock })} title={t('Timer anzeigen: {time}', { time: clock })}><span className="live-dot" aria-hidden="true"/><span className="floating-clock">{clock}</span></button>;
  const project = projects.find(p => p.id === timer.project_id);
  const tooLong = elapsed > 24 * 3600;
  return <section className="floating-timer" aria-label={t('Laufender Timer')}>
    <div className="floating-timer-top"><span className="live-dot" aria-hidden="true"/><span className="floating-clock" aria-label={t('Timer: {time}', { time: clock })}>{clock}</span><button type="button" className="icon-button" aria-label={t('Timer minimieren')} title={t('Timer minimieren')} onClick={() => remember('mini')}><Minus size={16}/></button></div>
    <button type="button" className="project-text-link floating-timer-project" onClick={onOpen}>{project && <span className="color-dot" style={{ backgroundColor: project.color }}/>}<strong>{project?.name || t('Projekt in anderem Workspace')}</strong><ArrowUpRight size={12}/></button>
    {timer.workspace_id !== workspace.id && <small>{t('Workspace: {name}', { name: workspaces.find(w => w.id === timer.workspace_id)?.name || t('anderer Workspace') })}</small>}
    <button className="button timer-stop full" disabled={busy || elapsed < 60 || tooLong} onClick={() => void run(() => service.stopTimer(timer.id), t('Timer gestoppt. Deine Zeit wurde gespeichert.'))}><Square size={15} fill="currentColor"/>{elapsed < 60 ? t('Speichern ab 1 Minute') : t('Stoppen & speichern')}</button>
  </section>;
}
function TimerPanel({ data, workspace, workspaces, service, run, busy, setModal }: { data: Dataset; workspace: Workspace; workspaces: Workspace[]; service: Service; run: Run; busy: boolean; setModal: (m: Modal) => void }) {
  const { t } = useI18n();
  const [project, setProject] = useState(data.projects.find(p => p.status === 'active')?.id || ''); const [task, setTask] = useState(''); const [note, setNote] = useState(''); const [billable, setBillable] = useState(true);
  useEffect(() => { if (!data.projects.some(p => p.id === project && p.status === 'active')) setProject(data.projects.find(p => p.status === 'active')?.id || ''); }, [data.projects, project]);
  useEffect(() => { if (task && !data.tasks.some(x => x.id === task && x.project_id === project && x.status !== 'done')) setTask(''); }, [data.tasks, task, project]);
  const { elapsed, clock } = useTimerClock(data.timer); const tooLong = elapsed > 24 * 3600;
  return <section className={`timer-panel ${data.timer ? 'running' : ''}`}><div className="timer-heading"><span className="eyebrow">{data.timer ? t('DU BIST IM FLOW') : t('EINS NACH DEM ANDEREN')}</span><span className={data.timer ? 'live-dot' : 'timer-star'}>{!data.timer && '✳'}</span></div><h2>{data.timer ? t('Deine Zeit läuft.') : t('Fokus an. Timer los.')}</h2><div className="timer-clock" aria-label={t('Timer: {time}', { time: clock })}>{clock}</div>{data.timer ? <><div className="running-info"><strong>{data.projects.find(p => p.id === data.timer!.project_id)?.name || t('Projekt in anderem Workspace')}</strong><p>{data.timer.note || t('Konzentriert bei der Sache.')}</p>{data.timer.workspace_id !== workspace.id && <small>{t('Workspace: {name}', { name: workspaces.find(w => w.id === data.timer!.workspace_id)?.name || t('anderer Workspace') })}</small>}</div>{tooLong && <Notice kind="info">{t('Dieser Timer läuft länger als 24 Stunden. Verwirf ihn und erfasse die korrekte Zeit manuell.')}</Notice>}<button className="button timer-stop full" disabled={busy || elapsed < 60 || tooLong} onClick={() => void run(() => service.stopTimer(data.timer!.id), t('Timer gestoppt. Deine Zeit wurde gespeichert.'))}><Square size={15} fill="currentColor"/>{elapsed < 60 ? t('Speichern ab 1 Minute') : t('Stoppen & speichern')}</button><button className="text-button timer-discard" disabled={busy} onClick={() => setModal({ type: 'confirm', title: t('Timer verwerfen?'), text: t('Die laufende Zeit wird nicht als Arbeitszeit gespeichert. Du kannst sie anschließend manuell erfassen.'), label: t('Timer verwerfen'), action: () => service.discardTimer(data.timer!.id) })}>{t('Timer verwerfen')}</button></> : <form onSubmit={e => { e.preventDefault(); void run(() => service.startTimer({ workspace_id: workspace.id, project_id: project, note: note.trim(), billable, task_id: task || null }), t('Timer gestartet. Guter Flow!')); }}><Field label={t('Projekt')}><SelectMenu label={t('Projekt')} required placeholder={t('Projekt auswählen')} value={project} onChange={setProject} options={data.projects.filter(p => p.status === 'active').map(p => projectOption(p))}/></Field><Field label={t('Aufgabe (optional)')}><SelectMenu label={t('Aufgabe (optional)')} placeholder={t('Ohne Aufgabe')} value={task} onChange={setTask} options={[{ value: '', label: t('Ohne Aufgabe') }, ...data.tasks.filter(x => x.project_id === project && x.status !== 'done').map(x => ({ value: x.id, label: x.title }))]}/></Field><Field label={t('Woran arbeitest du?')}><input maxLength={2000} value={note} onChange={e => setNote(e.target.value)} placeholder={t('Zum Beispiel: Konzept & Gestaltung')}/></Field><label className="checkbox-field"><input type="checkbox" checked={billable} onChange={e => setBillable(e.target.checked)}/> {t('Abrechenbar')}</label><button className="button timer-start full" disabled={busy || !project}><Play size={16} fill="currentColor"/> {t('Timer starten')}</button></form>}</section>;
}
function Times({ data, userId, manager, range, workspace, workspaces, setModal, service, run, busy, route, onNavigate, onShowQueue }: { data: Dataset; userId: string; manager: boolean; range: { from: string; to: string }; workspace: Workspace; workspaces: Workspace[]; setModal: (m: Modal) => void; service: Service; run: Run; busy: boolean; route: WorkflowRoute; onNavigate:(target:WorkflowTarget)=>void; onShowQueue:()=>void }) {
  const { t } = useI18n();
  const scope=manager?route.timeScope:'own',status=route.entryStatus,project=route.projectId||'all'; const setScope=(timeScope:'own'|'team')=>onNavigate({view:'time',timeScope}); const setStatus=(entryStatus:string)=>onNavigate({view:'time',entryStatus:entryStatus as WorkflowRoute['entryStatus']}); const setProject=(id:string)=>onNavigate({view:'time',projectId:id==='all'?'':id}); const filtered = data.entries.filter(e => (scope === 'team' || e.user_id === userId) && (status === 'all' || e.status === status) && (project === 'all' || e.project_id === project)); const drafts = data.entries.filter(e => e.user_id === userId && e.status === 'draft'); const submitted = filtered.filter(e => e.status === 'submitted').slice(0, 500);
  const submittedInRange = data.entries.filter(e => e.status === 'submitted').length;
  const queueBeyondRange = manager && data.queue.count > 0 && data.queue.oldest !== null && (data.queue.oldest < range.from || data.queue.count > submittedInRange);
  return <>{queueBeyondRange && <div className="queue-notice"><Notice kind="info">{t('{count} eingereichte Zeiten warten auf Freigabe – teils außerhalb des gewählten Zeitraums.', { count: data.queue.count })} <button className="text-button" onClick={onShowQueue}>{t('Alle offenen Freigaben anzeigen')}</button></Notice></div>}<div className="times-timer"><TimerPanel data={data} workspace={workspace} workspaces={workspaces} service={service} run={run} busy={busy} setModal={setModal}/></div><div className="list-toolbar times-toolbar"><div className="filter-group">{manager && <div className="segmented"><button aria-pressed={scope === 'own'} className={scope === 'own' ? 'selected' : ''} onClick={() => setScope('own')}>{t('Meine Zeiten')}</button><button aria-pressed={scope === 'team'} className={scope === 'team' ? 'selected' : ''} onClick={() => setScope('team')}>{t('Teamzeiten')}</button></div>}<SelectMenu compact label={t('Zeitstatus filtern')} value={status} onChange={setStatus} searchable={false} options={[{ value: 'all', label: t('Alle Status') }, { value: 'draft', label: t('Entwurf') }, { value: 'submitted', label: t('Eingereicht') }, { value: 'approved', label: t('Freigegeben') }]}/><SelectMenu compact label={t('Projekt filtern')} value={project} onChange={setProject} options={[{ value: 'all', label: t('Alle Projekte') }, ...data.projects.map(p => projectOption(p, true))]} tabs={projectTabs(data.projects, t)}/></div><button className="button secondary small" disabled={!filtered.length} onClick={() => downloadCsv(entriesCsv(filtered, data.projects, data.members), `vave-log-time-${range.from}-${range.to}.csv`)}><ArrowDownToLine size={16}/> CSV</button></div><section className="panel table-panel"><div className="table-summary"><span><strong>{filtered.length}</strong> {t('Zeiteinträge')}</span><strong>{minutesLabel(sum(filtered))}</strong></div>{filtered.length === 0 ? <Empty title={t('Zeit für einen Anfang.')} text={t('Für diesen Zeitraum und diese Filter gibt es noch keine Zeiten.')}/> : <div className="table-scroll"><table><thead><tr><th>{t('Datum / Person')}</th><th>{t('Projekt / Beschreibung')}</th><th>{t('Dauer')}</th><th>{t('Status')}</th><th><span className="sr-only">{t('Aktionen')}</span></th></tr></thead><tbody>{filtered.map(entry => { const p = data.projects.find(p => p.id === entry.project_id); const member = data.members.find(m => m.user_id === entry.user_id); return <tr key={entry.id}><td><strong>{longDate(entry.work_date)}</strong><small>{member?.display_name || member?.email || t('Teammitglied')}</small></td><td><div className="table-project"><span className="color-dot" style={{ backgroundColor: p?.color }}/><button className="project-text-link" onClick={()=>onNavigate({view:'projects',projectId:entry.project_id})}><strong>{p?.name || t('Projekt')}</strong><ArrowUpRight size={12}/></button></div><small className="entry-note">{entry.task_id && <>{data.tasks.find(x => x.id === entry.task_id)?.title ?? t('Gelöschte Aufgabe')} · </>}{entry.note || t('Keine Beschreibung')}</small>{entry.billable && <span className="billable-tag">{t('Abrechenbar')}</span>}</td><td className="nowrap"><strong>{minutesLabel(entry.minutes)}</strong></td><td><Status value={entry.status}/></td><td><div className="row-actions">{entry.user_id === userId && entry.status === 'draft' && <><button className="icon-button" aria-label={t('Zeit vom {date} bearbeiten', { date: longDate(entry.work_date) })} disabled={busy} onClick={() => setModal({ type: 'entry', item: entry })}><Pencil size={16}/></button><button className="icon-button delete-button" aria-label={t('Zeit vom {date} löschen', { date: longDate(entry.work_date) })} disabled={busy} onClick={() => setModal({ type: 'confirm', title: t('Zeiteintrag löschen?'), text: locale => translate('{time} vom {date} werden dauerhaft gelöscht.', locale, { time: minutesLabel(entry.minutes, locale), date: longDate(entry.work_date, locale) }), label: t('Eintrag löschen'), action: () => service.deleteEntry(entry.id) })}><Trash2 size={16}/></button></>}{manager && entry.status === 'approved' && <button className="icon-button" aria-label={t('Freigabe für {name} aufheben', { name: member?.display_name || t('Teammitglied') })} title={t('Freigabe aufheben')} disabled={busy} onClick={() => setModal({ type: 'confirm', title: t('Freigabe aufheben?'), text: t('Der Eintrag wird wieder zum Entwurf. Die Person kann ihn ändern und erneut einreichen. Bereits fakturierte Zeiten lassen sich nicht zurückholen.'), label: t('Freigabe aufheben'), action: () => service.revokeApproval(entry.id) })}><RotateCcw size={16}/></button>}{manager && entry.status === 'submitted' && <><button className="icon-button approve-button" aria-label={t('Zeit von {name} freigeben', { name: member?.display_name || t('Teammitglied') })} title={t('Freigeben')} disabled={busy} onClick={() => void run(() => service.reviewEntry({ id: entry.id, approve: true }), t('Zeiteintrag freigegeben.'))}><Check size={18}/></button><button className="icon-button delete-button" aria-label={t('Zur Überarbeitung zurückgeben')} title={t('Zur Überarbeitung zurückgeben')} disabled={busy} onClick={() => setModal({ type: 'confirm', title: t('Zeit zurückgeben?'), text: t('Der Eintrag wird wieder zum Entwurf. Die Person kann ihn korrigieren und erneut einreichen.'), label: t('Zurückgeben'), action: () => service.reviewEntry({ id: entry.id, approve: false }) })}><X size={18}/></button></>}{!manager && entry.status !== 'draft' && <ShieldCheck size={16} className="muted" aria-label={t('Eintrag ist gesperrt')}/>}</div></td></tr>; })}</tbody></table></div>}</section>{manager && submitted.length > 1 && <div className="submit-strip"><div><CheckCheck size={25}/><div><strong>{t('Sammel-Freigabe.')}</strong><p>{t('{count} eingereichte Zeiten in der aktuellen Ansicht · {time}.', { count: submitted.length, time: minutesLabel(sum(submitted)) })}</p></div></div><button className="button primary" disabled={busy} onClick={() => setModal({ type: 'confirm', title: t('Alle angezeigten Zeiten freigeben?'), text: locale => translate('{count} eingereichte Zeiten ({time}) aus der aktuellen Ansicht werden freigegeben. Inzwischen anders entschiedene Einträge werden übersprungen.', locale, { count: submitted.length, time: minutesLabel(sum(submitted), locale) }), label: t('Alle freigeben'), action: () => service.reviewEntries({ workspace_id: workspace.id, ids: submitted.map(e => e.id), approve: true }) })}>{t('Alle freigeben')} <Check size={17}/></button></div>}{drafts.length > 0 && <div className="submit-strip"><div><CheckCheck size={25}/><div><strong>{t('Alles richtig erfasst?')}</strong><p>{t('{count} deiner Entwürfe · {time} im gesamten gewählten Zeitraum.', { count: drafts.length, time: minutesLabel(sum(drafts)) })}</p></div></div><button className="button primary" disabled={busy} onClick={() => setModal({ type: 'confirm', title: t('Zeiten einreichen?'), text: locale => translate('Alle {count} eigenen Entwürfe vom {from} bis {to} ({time}) werden zur Prüfung eingereicht – unabhängig von den angezeigten Filtern. Danach sind sie für dich gesperrt, bis die Leitung sie zurückgibt.', locale, { count: drafts.length, from: shortDate(range.from, locale), to: shortDate(range.to, locale), time: minutesLabel(sum(drafts), locale) }), label: t('Zeiten einreichen'), action: () => service.submitEntries({ workspace_id: workspace.id, from: range.from, to: range.to }) })}>{t('Zeiten einreichen')} <ArrowRight size={17}/></button></div>}</>;
}
function Reports({ data, range, manager, route, service, workspace, onNavigate }: { data: Dataset; range: { from: string; to: string }; manager: boolean; route:WorkflowRoute; service: Service; workspace: Workspace; onNavigate:(target:WorkflowTarget)=>void }) {
  const { t } = useI18n();
  const [absences, setAbsences] = useState<Absence[] | null>(null);
  useEffect(() => { if (!manager) return; let alive = true; Promise.resolve().then(() => service.listAbsences(workspace.id, range.from, range.to)).then(list => { if (alive) setAbsences(list); }).catch(() => { if (alive) setAbsences([]); }); return () => { alive = false; }; }, [manager, service, workspace.id, range.from, range.to, data]);
  const project=route.projectId||'all',person=manager?(route.personId||'all'):'all',status=route.entryStatus; const setProject=(id:string)=>onNavigate({view:'reports',projectId:id==='all'?'':id}); const setPerson=(id:string)=>onNavigate({view:'reports',personId:id==='all'?'':id}); const setStatus=(entryStatus:string)=>onNavigate({view:'reports',entryStatus:entryStatus as WorkflowRoute['entryStatus']}); const entries = data.entries.filter(e => (project === 'all' || e.project_id === project) && (person === 'all' || e.user_id === person) && (status === 'all' || e.status === status)); const total = sum(entries); const billable = sum(entries.filter(e => e.billable));
  return <><div className="list-toolbar"><div className="filter-group"><label className="inline-field"><span>{t('Projekt')}</span><SelectMenu compact label={t('Projekt')} value={project} onChange={setProject} options={[{ value: 'all', label: t('Alle Projekte') }, ...data.projects.map(p => projectOption(p, true))]} tabs={projectTabs(data.projects, t)}/></label>{manager && <label className="inline-field"><span>{t('Person')}</span><SelectMenu compact label={t('Person')} value={person} onChange={setPerson} options={[{ value: 'all', label: t('Ganzes Team') }, ...data.members.map(m => memberOption(m))]} tabs={memberTabs(data.members, t)}/></label>}<label className="inline-field"><span>{t('Status')}</span><SelectMenu compact label={t('Status')} value={status} onChange={setStatus} searchable={false} options={[{ value: 'all', label: t('Alle Status') }, { value: 'draft', label: t('Entwurf') }, { value: 'submitted', label: t('Eingereicht') }, { value: 'approved', label: t('Freigegeben') }]}/></label></div><button className="button secondary small" disabled={!entries.length} onClick={() => downloadCsv(entriesCsv(entries, data.projects, data.members), `vave-log-report-${range.from}-${range.to}.csv`)}><ArrowDownToLine size={16}/> {t('CSV exportieren')}</button></div><div className="metric-grid report-metrics"><Metric label={manager ? t('Erfasste Teamzeit') : t('Deine erfasste Zeit')} value={minutesLabel(total)} sub={t('{count} Einträge nach Filter', { count: entries.length })} icon={<Clock3 size={19}/>} featured/><Metric label={t('Abrechenbar')} value={minutesLabel(billable)} sub={total ? t('{percent} % der erfassten Zeit', { percent: Math.round(billable / total * 100) }) : t('Noch keine Zeiten')} icon={<Activity size={19}/>}/><Metric label={t('Freigegebene Zeit')} value={minutesLabel(sum(entries.filter(e => e.status === 'approved')))} sub={t('Bereit zur weiteren Verarbeitung')} icon={<ShieldCheck size={19}/>}/></div><section className="panel"><div className="panel-heading"><div><p className="eyebrow">{t('PROJEKTBUDGETS')}</p><h2>{t('Wo eure Zeit hinfließt.')}</h2><p>{t('Erfasste Zeit nach Filter im Verhältnis zum gesamten Projektbudget.')}</p></div></div><Notice kind="info">{t(manager ? 'Die Auswertung zeigt ausschließlich den gewählten Zeitraum. Zeiten außerhalb davon sind nicht enthalten. Ein verbleibendes Gesamtbudget lässt sich daraus nicht ableiten.' : 'Die Auswertung zeigt ausschließlich den gewählten Zeitraum und deine eigenen Zeiten. Zeiten außerhalb davon sind nicht enthalten. Ein verbleibendes Gesamtbudget lässt sich daraus nicht ableiten.')}</Notice>{!data.projects.length ? <Empty title={t('Noch keine Projekte.')} text={t('Sobald Projekte und Zeiten vorhanden sind, erscheint hier eure Auswertung.')}/> : <div className="budget-list">{data.projects.filter(p => project === 'all' || p.id === project).map(p => { const used = sum(entries.filter(e => e.project_id === p.id)); const percent = p.budget_minutes ? Math.round(used / p.budget_minutes * 100) : 0; return <div className="budget-row" key={p.id}><ProjectMark project={p}/><div className="budget-name"><button className="project-text-link" onClick={()=>onNavigate({view:'projects',projectId:p.id})}><strong>{p.name}</strong><ArrowUpRight size={12}/></button><small>{p.client || p.code}</small></div><div className="budget-bar"><div className="progress-track"><div style={{ width: `${Math.min(percent,100)}%`, backgroundColor: p.color }}/></div><small>{p.budget_minutes ? t('{percent} % des Gesamtbudgets im Zeitraum', { percent }) : t('Kein Budget festgelegt')}</small></div><div className="budget-total"><strong>{minutesLabel(used)}</strong><small>{p.budget_minutes ? t('von {time}', { time: minutesLabel(p.budget_minutes) }) : t('im Zeitraum')}</small></div></div>; })}</div>}</section>{manager && <section className="panel"><div className="panel-heading"><div><p className="eyebrow">{t('AUSLASTUNG')}</p><h2>{t('Kapazität trifft Wirklichkeit.')}</h2><p>{t('Soll = Kapazität je Werktag (Mo–Fr) im Zeitraum, abzüglich eingetragener Abwesenheiten. Kapazität und Abwesenheiten pflegst du im Team-Bereich.')}</p></div></div>{(() => { const report = utilization(data.members, data.entries, absences ?? [], range); const shown = data.members.filter(m => (person === 'all' || m.user_id === person) && m.role !== 'disabled'); return shown.length === 0 ? <Empty title={t('Zeit für einen Anfang.')} text={t('Für diesen Zeitraum und diese Filter gibt es noch keine Zeiten.')}/> : <div className="table-scroll"><table><thead><tr><th>{t('Person')}</th><th>{t('Kapazität/Woche')}</th><th>{t('Abwesend (Werktage)')}</th><th>{t('Soll')}</th><th>{t('Ist')}</th><th>{t('Abrechenbar')}</th><th>{t('Auslastung')}</th></tr></thead><tbody>{shown.map(m => { const u = report.get(m.user_id); if (!u) return null; const percent = u.expectedMinutes ? Math.round(u.actualMinutes / u.expectedMinutes * 100) : null; return <tr key={m.user_id}><td><div className="person-cell"><span className="avatar">{initials(m.display_name || m.email)}</span><strong>{m.display_name || m.email}</strong></div></td><td>{u.capacityMinutes == null ? <span className="muted">{t('Nicht gepflegt')}</span> : minutesLabel(u.capacityMinutes)}</td><td>{u.absenceWorkdays}</td><td>{u.expectedMinutes == null ? <span className="muted">–</span> : minutesLabel(u.expectedMinutes)}</td><td><strong>{minutesLabel(u.actualMinutes)}</strong></td><td>{minutesLabel(u.billableMinutes)}</td><td>{percent == null ? <span className="muted">–</span> : <div className="budget-bar"><div className="progress-track"><div style={{ width: `${Math.min(percent, 100)}%`, backgroundColor: percent > 110 ? '#a33d32' : '#641dff' }}/></div><small>{percent} %</small></div>}</td></tr>; })}</tbody></table></div>; })()}</section>}{manager && <section className="panel team-report"><div className="panel-heading"><div><p className="eyebrow">{t('TEAMÜBERSICHT')}</p><h2>{t('Viele Köpfe. Gemeinsamer Fortschritt.')}</h2></div></div><div className="member-report-grid">{data.members.filter(m => person === 'all' || person === m.user_id).map(m => <div className="member-report" key={m.user_id}><span className="avatar">{initials(m.display_name || m.email)}</span><div><strong>{m.display_name || m.email}</strong><small>{t('{count} Einträge', { count: entries.filter(e => e.user_id === m.user_id).length })}</small></div><strong>{minutesLabel(sum(entries.filter(e => e.user_id === m.user_id)))}</strong></div>)}</div></section>}</>;
}
function CapacityCell({ member, service, run, busy }: { member: Membership; service: Service; run: Run; busy: boolean }) {
  const { t } = useI18n();
  const [hours, setHours] = useState(member.weekly_capacity_minutes == null ? '' : String(member.weekly_capacity_minutes / 60));
  const stored = member.weekly_capacity_minutes == null ? '' : String(member.weekly_capacity_minutes / 60);
  function save() {
    const minutes = hours.trim() === '' ? null : Math.round(Number(hours) * 60);
    if (minutes !== null && (!Number.isFinite(minutes) || minutes < 0 || minutes > 6000)) return;
    void run(() => service.setMemberCapacity({ workspace_id: member.workspace_id, user_id: member.user_id, minutes }), t('Gespeichert.'));
  }
  return <span className="capacity-cell"><input aria-label={t('Kapazität von {name} in Stunden pro Woche', { name: member.display_name || member.email })} type="number" min="0" max="100" step="0.5" value={hours} placeholder="–" onChange={e => setHours(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); save(); } }}/><span className="muted">{t('h/Woche')}</span>{hours !== stored && <button type="button" className="icon-button" aria-label={t('Kapazität speichern')} title={t('Kapazität speichern')} disabled={busy} onClick={save}><Check size={15}/></button>}</span>;
}
const ABSENCE_KINDS = { vacation: 'Urlaub', sick: 'Krank', holiday: 'Feiertag', other: 'Sonstiges' } as const;
function AbsencesPanel({ absences, members, userId, workspace, service, run, busy, setModal, today }: { absences: Absence[] | null; members: Membership[]; userId: string; workspace: Workspace; service: Service; run: Run; busy: boolean; setModal: (m: Modal) => void; today: string }) {
  const { t } = useI18n();
  const [adding, setAdding] = useState(false);
  const name = (id: string) => { const m = members.find(x => x.user_id === id); return m?.display_name || m?.email || t('Teammitglied'); };
  function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const f = new FormData(e.currentTarget);
    void run(() => service.saveAbsence({ workspace_id: workspace.id, user_id: String(f.get('person')), starts_on: String(f.get('from')), ends_on: String(f.get('to')), kind: String(f.get('kind')) as Absence['kind'], note: String(f.get('note') || '').trim() }), t('Gespeichert.'));
    setAdding(false);
  }
  return <section className="panel"><div className="panel-heading"><div><p className="eyebrow">{t('ABWESENHEITEN')}</p><h2>{t('Wer ist wann nicht da?')}</h2></div><button className="button secondary small" onClick={() => setAdding(a => !a)}><Plus size={15}/>{t('Abwesenheit eintragen')}</button></div>
    {adding && <form className="form-stack absence-form" onSubmit={submit}><div className="form-grid"><Field label={t('Person')}><SelectMenu label={t('Person')} name="person" required defaultValue={userId} options={members.filter(m => !m.is_demo && m.role !== 'disabled').map(m => ({ value: m.user_id, label: m.display_name || m.email }))}/></Field><Field label={t('Art')}><SelectMenu label={t('Art')} name="kind" searchable={false} defaultValue="vacation" options={Object.entries(ABSENCE_KINDS).map(([value, label]) => ({ value, label: t(label) }))}/></Field><Field label={t('Von')}><input type="date" name="from" required defaultValue={today} min="2000-01-01" max="2100-12-31"/></Field><Field label={t('Bis')}><input type="date" name="to" required defaultValue={today} min="2000-01-01" max="2100-12-31"/></Field></div><Field label={t('Notiz')}><input name="note" maxLength={500}/></Field><div className="button-row"><button className="button primary small" disabled={busy}>{t('Speichern')}</button><button type="button" className="text-button" onClick={() => setAdding(false)}>{t('Abbrechen')}</button></div></form>}
    {absences === null ? <p className="muted">{t('Workspace wird aktualisiert …')}</p> : absences.length === 0 ? <p className="muted">{t('Keine Abwesenheiten eingetragen.')}</p> : <div className="invite-list">{absences.map(a => <div className="invite-row" key={a.id}><div><strong>{name(a.user_id)}</strong><small>{t(ABSENCE_KINDS[a.kind])} · {longDate(a.starts_on)} – {longDate(a.ends_on)}{a.note ? ` · ${a.note}` : ''}</small></div><button className="icon-button delete-button" aria-label={t('Abwesenheit von {name} löschen', { name: name(a.user_id) })} title={t('Abwesenheit löschen')} disabled={busy} onClick={() => setModal({ type: 'confirm', title: t('Abwesenheit löschen?'), text: t('Der Eintrag wird dauerhaft entfernt.'), label: t('Abwesenheit löschen'), action: () => service.deleteAbsence(a.id) })}><Trash2 size={15}/></button></div>)}</div>}
  </section>;
}
function Team({ data, userId, role, service, run, busy, workspace, setModal, onNavigate }: { data: Dataset; userId: string; role: Role; service: Service; run: Run; busy: boolean; workspace: Workspace; setModal: (m: Modal) => void; onNavigate:(target:WorkflowTarget)=>void }) {
  const { t, locale } = useI18n();
  const [invitations, setInvitations] = useState<Invitation[] | null>(null);
  const [absences, setAbsences] = useState<Absence[] | null>(null);
  const today = dateInZone(workspace.timezone);
  // Fenster unter dem 366-Tage-Deckel von dateRangeSchema halten.
  useEffect(() => { let alive = true; Promise.resolve().then(() => service.listAbsences(workspace.id, addDays(today, -30), addDays(today, 330))).then(list => { if (alive) setAbsences(list); }).catch(() => { if (alive) setAbsences([]); }); return () => { alive = false; }; }, [service, workspace.id, data, today]);
  // Open invitations live outside the Dataset: only owners/managers may list
  // them, and the Team view is the only place that shows them.
  useEffect(() => { let alive = true; service.listInvitations(workspace.id).then(list => { if (alive) setInvitations(list); }).catch(() => { if (alive) setInvitations([]); }); return () => { alive = false; }; }, [service, workspace.id, data]);
  return <><div className="team-intro"><span className="large-number">{String(data.members.length).padStart(2,'0')}</span><div><h2>{t('Menschen. Ein Workspace.')}</h2><p>{t('Jede Person bringt etwas mit. Zusammen wird etwas draus.')}</p></div><Users size={44}/></div>{data.demo&&<p className="muted">{agencyText(locale,'samplePeopleNote')}</p>}<section className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>{t('Person')}</th><th>{data.demo?agencyText(locale,'teamIdentity'):t('E-Mail-Adresse')}</th><th>{t('Rolle')}</th><th>{t('Kapazität/Woche')}</th></tr></thead><tbody>{data.members.map(member => <tr key={member.user_id}><td><div className="person-cell"><span className="avatar">{initials(member.display_name || member.email)}</span><div><strong><button className="project-text-link" onClick={()=>onNavigate({view:'reports',personId:member.user_id,projectId:'',entryStatus:'all'})}>{member.display_name || t('Teammitglied')}<ArrowUpRight size={12}/></button>{member.is_demo&&<span className="you-label">{agencyText(locale,'samplePerson')}</span>}{member.user_id === userId && <span className="you-label">{t('Du')}</span>}</strong>{member.is_demo&&<small className="muted">{[member.demo_title,member.demo_studio].filter(Boolean).join(' · ')}</small>}</div></div></td><td>{member.is_demo?<><span>{agencyText(locale,member.demo_origin==='public'?'samplePublic':member.demo_origin==='fictional'?'sampleFictional':'sampleProfile')}</span><small>{agencyText(locale,'sampleAccess')}</small></>:<>{member.email}{data.demo&&<small>{agencyText(locale,'realAccount')}</small>}</>}</td><td>{role === 'owner' && !member.is_demo ? <SelectMenu compact className="team-role-cell" label={t('Rolle von {name}', { name: member.display_name || member.email })} disabled={busy} value={member.role} searchable={false} options={(['member','manager','owner','disabled'] as Role[]).map(r => ({ value: r, label: t(roleNames[r]) }))} onChange={value => { const next = value as Role; setModal({ type: 'confirm', title: t('Rolle ändern?'), text: locale => translate('{name} erhält die Rolle „{role}“.', locale, { name: member.display_name || member.email, role: translate(roleNames[next], locale) }) + (next === 'disabled' ? translate(' Der Workspace-Zugriff wird entzogen. Ein laufender Timer wird ohne Zeitbuchung verworfen. Historische Zeiten bleiben erhalten.', locale) : '') + (member.user_id === userId ? translate(' Dadurch können sich deine eigenen Zugriffsrechte ändern.', locale) : ''), label: t('Rolle ändern'), action: () => service.setMemberRole({ workspace_id: workspace.id, user_id: member.user_id, role: next }) }); }}/> : <span className={`role-badge role-${member.role}`}>{t(roleNames[member.role])}</span>}</td><td>{member.is_demo ? <span className="muted">–</span> : <CapacityCell member={member} service={service} run={run} busy={busy}/>}</td></tr>)}</tbody></table></div></section>{!!invitations?.length && <section className="panel"><div className="panel-heading"><div><p className="eyebrow">{t('OFFENE EINLADUNGEN')}</p><h2>{t('Eingeladen, noch nicht dabei.')}</h2></div><span className="count-circle">{invitations.length}</span></div><div className="invite-list">{invitations.map(inv => <div className="invite-row" key={inv.id}><div><strong>{inv.email}</strong><small>{t(roleNames[inv.role])} · {t('gültig bis {date}', { date: longDate(inv.expires_at.slice(0, 10)) })}</small></div>{role === 'owner' && <button className="icon-button delete-button" aria-label={t('Einladung an {email} widerrufen', { email: inv.email })} title={t('Einladung widerrufen')} disabled={busy} onClick={() => setModal({ type: 'confirm', title: t('Einladung widerrufen?'), text: t('Die Person kann dem Workspace mit dieser Einladung nicht mehr beitreten. Du kannst sie jederzeit erneut einladen.'), label: t('Einladung widerrufen'), action: () => service.revokeInvitation(inv.id) })}><Trash2 size={16}/></button>}</div>)}</div></section>}<AbsencesPanel absences={absences} members={data.members} userId={userId} workspace={workspace} service={service} run={run} busy={busy} setModal={setModal} today={today}/><div className="role-guide"><div><ShieldCheck size={20}/><h3>{t('Inhaber:in')}</h3><p>{t('Verwaltet Einladungen und Rollen sowie Projekte und Teamzeiten.')}</p></div><div><FolderKanban size={20}/><h3>{t('Leitung')}</h3><p>{t('Verwaltet Projekte, sieht Teamzeiten und prüft eingereichte Zeiten.')}</p></div><div><Users size={20}/><h3>{t('Mitglied')}</h3><p>{t('Arbeitet an gemeinsamen Aufgaben und erfasst eigene Zeiten.')}</p></div></div></>;
}
function Settings({ onManageWorkspaces, hasOwnedWorkspaces, workspace, self, client, config, signOut }: { onManageWorkspaces:()=>void; hasOwnedWorkspaces:boolean; workspace: Workspace; self?: Membership; client: SupabaseClient; config: RuntimeConfig; signOut: () => Promise<void> }) {
  const { t, locale } = useI18n();
  const [copy, setCopy] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  async function reset() { if (!self?.email) return; setBusy(true); setMessage(''); setError(''); try { const { error } = await client.auth.resetPasswordForEmail(self.email, { redirectTo: appHref('?reset=1', config.appUrl) }); if (error) throw error; setMessage(t('Der Link zum Zurücksetzen wurde angefordert. Prüfe dein E-Mail-Postfach.')); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); } }
  return <div className="settings-grid"><section className="panel"><div className="panel-heading"><div><p className="eyebrow">{t('DEIN ARBEITSORT')}</p><h2>{workspace.name}</h2></div><span className="workspace-avatar">{initials(workspace.name)}</span></div><dl className="detail-list"><div><dt>{t('Zeitzone')}</dt><dd>{workspace.timezone}</dd></div><div><dt>{t('Währung')}</dt><dd>{workspace.currency}</dd></div><div><dt>{t('Deine Rolle')}</dt><dd>{t(roleNames[self?.role || 'member'])}</dd></div><div><dt>{t('Workspace-ID')}</dt><dd className="mono tiny">{workspace.id}</dd></div></dl><p className="tiny muted">{t('Zeitzone und Währung werden beim Anlegen festgelegt. Die Zeitzone bestimmt die Tagesgrenzen deiner Timer.')}</p></section><section className="panel"><div className="panel-heading"><div><p className="eyebrow">{t('DEIN ACCOUNT')}</p><h2>{self?.display_name || t('Dein Profil')}</h2></div><span className="avatar">{initials(self?.display_name || self?.email || t('Du'))}</span></div><dl className="detail-list"><div><dt>{t('E-Mail')}</dt><dd>{self?.email}</dd></div><div><dt>{t('Anmeldung')}</dt><dd><span className="verified"><Check size={14}/> {t('Bestätigte E-Mail')}</span></dd></div></dl>{error && <Notice>{error}</Notice>}{message && <Notice kind="success">{message}</Notice>}<div className="button-row"><button className="button secondary small" disabled={busy} onClick={() => void reset()}>{t('Passwort zurücksetzen')}</button><button className="button secondary small" onClick={() => void signOut()}><LogOut size={15}/> {t('Abmelden')}</button></div></section>{(self?.role==='owner'||hasOwnedWorkspaces)&&<section className="panel"><p className="eyebrow">{workspaceAdminText(locale,'owner')}</p><h2>{workspaceAdminText(locale,'title')}</h2><p className="muted">{workspaceAdminText(locale,'intro')}</p><button className="button secondary" type="button" onClick={onManageWorkspaces}>{workspaceAdminText(locale,'title')}</button></section>}<PwaSettings/><ConnectedApps client={client}/><section className="panel integration-panel"><span className="integration-symbol" aria-hidden="true">↗</span><p className="eyebrow">{t('DEIN WORKFLOW GEHT WEITER')}</p><h2>{t('VAVE.LOG für deine Tools.')}</h2><p className="muted">{t('Verbinde einen MCP-fähigen Client über OAuth. Der Zugriff erfolgt mit deinen Rechten und deiner ausdrücklichen Zustimmung.')}</p><Field label={t('MCP-Adresse')}><div className="copy-field"><code>{appHref('api/mcp', config.appUrl)}</code><button className="icon-button" aria-label={t('MCP-Adresse kopieren')} onClick={() => { void navigator.clipboard.writeText(appHref('api/mcp', config.appUrl)).then(() => setCopy(true)).catch(() => setError(t('Kopieren nicht möglich. Bitte markiere die Adresse manuell.'))); }}>{copy ? <Check size={17}/> : <Copy size={17}/>}</button></div></Field>{copy && <span role="status" className="tiny">{t('Adresse kopiert.')}</span>}<p className="tiny muted">{t('Der Supabase OAuth-Server und der Client müssen für diese Verbindung eingerichtet sein. Details stehen in der Betriebsanleitung.')}</p></section></div>;
}
// A ready-to-send message for the invited person; VAVE.LOG sends no email itself.
function InviteHelp({ appUrl }: { appUrl: string }) {
  const { t } = useI18n();
  const [state, setState] = useState<'idle' | 'copied' | 'manual'>('idle');
  const text = t('Hallo! Ich habe dich zu unserem VAVE.LOG-Workspace eingeladen.\n\n1. Öffne {url}\n2. Wähle „Jetzt registrieren“ und registriere dich mit genau dieser E-Mail-Adresse und einem eigenen Passwort.\n3. Bestätige deine E-Mail-Adresse über den Link aus deinem Postfach und melde dich an.\n\nDer Workspace wird dir beim ersten Anmelden automatisch zugeordnet. Falls du schon ein VAVE.LOG-Konto hast, reicht die Anmeldung.', { url: appUrl });
  return <>
    <button type="button" className="button secondary small invite-copy" onClick={() => {
      const clipboard = navigator.clipboard;
      if (!clipboard?.writeText) { setState('manual'); return; }
      clipboard.writeText(text).then(() => setState('copied'), () => setState('manual'));
    }}><Copy size={15}/> {t('Einladungstext kopieren')}</button>
    {state === 'copied' && <p className="tiny muted" role="status">{t('Einladungstext kopiert. Füge ihn in deine E-Mail oder Nachricht ein.')}</p>}
    {state === 'manual' && <><p className="tiny muted" role="status">{t('Kopieren nicht möglich — Text markieren und manuell kopieren.')}</p><textarea readOnly rows={8} value={text} onFocus={event => event.currentTarget.select()}/></>}
  </>;
}
function Editor({ modal, data, workspace, service, run, busy, onClose, appUrl, errorDetail, onNavigate, client }: { modal: Modal; data: Dataset; workspace: Workspace; service: Service; run: Run; busy: boolean; onClose: () => void; appUrl: string; errorDetail?: string; onNavigate:(target:WorkflowTarget)=>void; client: SupabaseClient }) {
  const { t, locale } = useI18n();
  const id = useRef(('item' in modal ? modal.item?.id : undefined) || crypto.randomUUID()); const [error, setError] = useState(''); const [deleting, setDeleting] = useState(false); const [sendLink, setSendLink] = useState(false);
  const [entryProject, setEntryProject] = useState(() => (modal.type === 'entry' && (modal.item?.project_id || modal.projectId)) || data.projects.find(p => p.status === 'active')?.id || '');
  const item = 'item' in modal ? modal.item : undefined;
  const title = modal.type === 'confirm' ? modal.title : modal.type === 'project' ? (item ? t('Projekt bearbeiten') : t('Neues Projekt')) : modal.type === 'task' ? (item ? t('Aufgabe bearbeiten') : t('Neue Aufgabe')) : modal.type === 'entry' ? (item ? t('Zeit bearbeiten') : t('Zeit erfassen')) : t('Person einladen');
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const f = new FormData(e.currentTarget); setError(''); let action: () => Promise<unknown>;
    if (modal.type === 'confirm') action = modal.action;
    else if (modal.type === 'project') action = () => service.saveProject({ id: id.current, workspace_id: workspace.id, name: String(f.get('name')).trim(), code: String(f.get('code')).trim(), client: String(f.get('client')).trim(), budget_minutes: Math.round(Number(f.get('budget')) * 60), status: String(f.get('status')) as Project['status'], color: String(f.get('color')), due_date:String(f.get('deadline')||'')||null });
    else if (modal.type === 'task') action = () => service.saveTask({ id: id.current, workspace_id: workspace.id, project_id: String(f.get('project')), title: String(f.get('title')).trim(), status: String(f.get('status')) as Task['status'], assignee_id: String(f.get('assignee')) || null, due_date: String(f.get('due')) || null, estimated_minutes:String(f.get('estimate')||'').trim()===''?null:Math.round(Number(f.get('estimate'))*60), is_milestone:f.get('milestone')==='on' });
    else if (modal.type === 'entry') { const minutes = Number(f.get('hours')) * 60 + Number(f.get('minutes')); if (!Number.isInteger(minutes) || minutes < 1 || minutes > 1440) { setError(t('Bitte erfasse zwischen 1 und 1.440 Minuten.')); return; } action = () => service.saveEntry({ id: id.current, workspace_id: workspace.id, project_id: String(f.get('project')), work_date: String(f.get('date')), minutes, note: String(f.get('note')).trim(), billable: f.get('billable') === 'on', task_id: String(f.get('task') || '') || null }); }
    else { const email = String(f.get('email')).trim(); const sendLink = !!f.get('sendlink'); action = async () => {
      await service.inviteMember({ workspace_id: workspace.id, email, role: String(f.get('role')) as 'member' | 'manager' });
      if (!sendLink) return;
      // The invitation is stored either way; a failed email must say so, not undo it.
      const { error: otpError } = await client.auth.signInWithOtp({ email, options: { emailRedirectTo: appUrl, shouldCreateUser: true, data: { locale } } });
      if (otpError) throw new Error('Die Einladung ist gespeichert, aber der Anmeldelink konnte nicht gesendet werden (z. B. Rate-Limit). Teile den Website-Link manuell oder versuche es später erneut.');
    }; }
    const ok = await run(action, modal.type === 'invite' ? (f.get('sendlink') ? t('Einladung hinterlegt und Anmeldelink per E-Mail gesendet.') : t('Einladung hinterlegt. Teile den Website-Link mit der Person; es wurde keine Einladungs-E-Mail verschickt.')) : modal.type === 'confirm' ? t('Änderung gespeichert.') : t('Gespeichert.')); if (!ok) setError(t('Die Änderung wurde nicht bestätigt. Prüfe den Hinweis im Workspace und versuche es erneut.'));
  }
  const projectSelect = <Field label={t('Projekt')}><SelectMenu label={t('Projekt')} name="project" required placeholder={t('Projekt auswählen')} defaultValue={item && 'project_id' in item ? item.project_id : ('projectId' in modal && modal.projectId) || data.projects.find(p => p.status === 'active')?.id || ''} options={data.projects.filter(p => p.status === 'active' || (item && 'project_id' in item && item.project_id === p.id)).map(p => projectOption(p))}/></Field>;
  return <Dialog title={title} onClose={onClose} busy={busy}><form className="form-stack" onSubmit={submit}>{(errorDetail || error) && <Notice>{errorDetail || error}</Notice>}{modal.type === 'confirm' && <p className="confirm-copy">{typeof modal.text === 'function' ? modal.text(locale) : t(modal.text)}</p>}{modal.type === 'project' && <><Field label={t('Projektname')}><input name="name" required maxLength={160} defaultValue={modal.item?.name} placeholder={t('Zum Beispiel: Ein neuer Markenauftritt')}/></Field><div className="form-grid"><Field label={t('Projektcode')}><input name="code" required maxLength={24} defaultValue={modal.item?.code} placeholder="VAV-001"/></Field><Field label={t('Kunde')}><input name="client" maxLength={160} defaultValue={modal.item?.client} placeholder={t('Unternehmen oder Organisation')}/></Field></div><div className="form-grid"><Field label={t('Zeitbudget in Stunden')} hint={t('0 = kein Zeitbudget')}><input name="budget" type="number" required min="0" max="100000" step="any" defaultValue={(modal.item?.budget_minutes || 0) / 60}/></Field><Field label={t('Status')}><SelectMenu label={t('Status')} name="status" searchable={false} defaultValue={modal.item?.status || 'active'} options={[{ value: 'active', label: t('Aktiv') }, { value: 'paused', label: t('Pausiert') }, { value: 'archived', label: t('Archiviert') }]}/></Field></div><details className="planning-fields" open><summary><BarChart3 size={15}/>{wt(locale,'editPlanning')}</summary><Field label={wt(locale,'deadline')} hint={wt(locale,'deadlineHint')}><input aria-label={wt(locale,'deadline')} type="date" name="deadline" min="2000-01-01" max="2100-12-31" defaultValue={modal.item?.due_date||''}/></Field><p className="tiny muted">{insightText(locale,'autoHint')}</p></details><Field label={t('Projektfarbe')}><input className="color-input" type="color" name="color" defaultValue={modal.item?.color || '#641dff'}/></Field>{modal.item && <p className="tiny muted">{t('Archivierte Projekte bleiben mit ihren Zeiten und Aufgaben erhalten.')}</p>}</>}{modal.type === 'task' && <>{projectSelect}<Field label={t('Aufgabe')}><input name="title" required maxLength={240} defaultValue={modal.item?.title} placeholder={t('Was ist der nächste konkrete Schritt?')}/></Field><div className="form-grid"><Field label={t('Status')}><SelectMenu label={t('Status')} name="status" searchable={false} defaultValue={modal.item?.status || 'todo'} options={[{ value: 'todo', label: t('Offen') }, { value: 'doing', label: t('In Arbeit') }, { value: 'done', label: t('Erledigt') }]}/></Field><Field label={t('Fällig am')}><input name="due" type="date" min="2000-01-01" max="2100-12-31" defaultValue={modal.item?.due_date || ''}/></Field></div><TaskAssigneeSelect members={data.members} currentAssignee={modal.item?.assignee_id}/><Field label={insightText(locale,'estimateHours')} hint={insightText(locale,'estimateHint')}><input name="estimate" type="number" min="0.01" max="100000" step="any" defaultValue={modal.item?.estimated_minutes?modal.item.estimated_minutes/60:''} placeholder={wt(locale,'unknown')}/></Field><label className="checkbox-field"><input type="checkbox" name="milestone" defaultChecked={modal.item?.is_milestone??false}/>{insightText(locale,'milestone')}</label><p className="tiny muted">{insightText(locale,'milestoneEditorHint')}</p>{modal.item && (!deleting ? <button type="button" className="text-button danger-text" onClick={() => setDeleting(true)}><Trash2 size={15}/> {t('Aufgabe löschen')}</button> : <div className="confirm-inline"><p>{t('Diese Aufgabe dauerhaft löschen?')}</p><div className="button-row"><button className="button danger small" disabled={busy} type="button" onClick={() => void run(() => service.deleteTask(modal.item!.id), t('Aufgabe gelöscht.'))}>{t('Ja, löschen')}</button><button className="text-button" type="button" disabled={busy} onClick={() => setDeleting(false)}>{t('Behalten')}</button></div></div>)}</>}{modal.type === 'entry' && <><Field label={t('Projekt')}><SelectMenu label={t('Projekt')} name="project" required placeholder={t('Projekt auswählen')} value={entryProject} onChange={setEntryProject} options={data.projects.filter(p => p.status === 'active' || (modal.item && modal.item.project_id === p.id)).map(p => projectOption(p))}/></Field><Field label={t('Aufgabe (optional)')}><SelectMenu key={entryProject} label={t('Aufgabe (optional)')} name="task" placeholder={t('Ohne Aufgabe')} defaultValue={modal.item?.task_id && modal.item.project_id === entryProject ? modal.item.task_id : ''} options={[{ value: '', label: t('Ohne Aufgabe') }, ...data.tasks.filter(task => task.project_id === entryProject && (task.status !== 'done' || task.id === modal.item?.task_id)).map(task => ({ value: task.id, label: task.title }))]}/></Field><Field label={t('Datum')}><input type="date" min="2000-01-01" max="2100-12-31" name="date" required defaultValue={modal.item?.work_date || dateInZone(workspace.timezone)}/></Field><div className="form-grid"><Field label={t('Stunden')}><input type="number" name="hours" min="0" max="24" step="1" required defaultValue={Math.floor((modal.item?.minutes || 0) / 60)}/></Field><Field label={t('Minuten')}><input type="number" name="minutes" min="0" max="59" step="1" required defaultValue={(modal.item?.minutes || 30) % 60}/></Field></div><Field label={t('Beschreibung')}><textarea name="note" rows={3} maxLength={2000} defaultValue={modal.item?.note} placeholder={t('Woran hast du gearbeitet?')}/></Field><label className="checkbox-field"><input type="checkbox" name="billable" defaultChecked={modal.item?.billable ?? true}/> {t('Abrechenbar')}</label><p className="tiny muted">{t('Die Zeit wird als Entwurf gespeichert. Maximal 24 Stunden pro Tag; Zeitzone {timezone}.', { timezone: workspace.timezone })}</p></>}{modal.type === 'invite' && <><p className="muted">{t('Hinterlege die E-Mail-Adresse der Person. Die Einladung wird nach ihrer Anmeldung mit bestätigter E-Mail automatisch angenommen.')}</p><Field label={t('E-Mail-Adresse')}><input name="email" type="email" required maxLength={254} placeholder={t('person@studio.de')} autoComplete="off"/></Field><Field label={t('Rolle')}><SelectMenu label={t('Rolle')} name="role" searchable={false} defaultValue="member" options={[{ value: 'member', label: t('Mitglied') }, { value: 'manager', label: t('Leitung') }]}/></Field><label className="checkbox-field"><input type="checkbox" name="sendlink" checked={sendLink} onChange={e => setSendLink(e.target.checked)}/> {t('Anmeldelink direkt per E-Mail senden')}</label><p className="tiny muted">{t('Erstellt das Konto und schickt der Person einen Anmeldelink. Ein eigenes Passwort kann sie danach jederzeit über „Passwort vergessen?“ festlegen.')}</p><Notice kind="info">{sendLink ? t('Die Person erhält einen Anmeldelink per E-Mail an diese Adresse.') : <>{t('VAVE.LOG verschickt keine Einladungs-E-Mail. Teile anschließend diesen Website-Link:')} <span className="wrap-code">{appUrl}</span></>}</Notice><div className="invite-steps"><strong>{t('So geht es für die eingeladene Person weiter:')}</strong><ol><li>{t('Link öffnen und „Jetzt registrieren“ wählen — kein „Passwort vergessen“ nötig.')}</li><li>{t('Mit genau der eingeladenen E-Mail-Adresse registrieren und ein eigenes Passwort festlegen.')}</li><li>{t('E-Mail-Adresse über den Bestätigungslink im Postfach bestätigen und anmelden — der Workspace erscheint automatisch.')}</li></ol><p className="tiny muted">{t('Hat die Person schon ein VAVE.LOG-Konto, reicht die normale Anmeldung. Die Einladung gilt 14 Tage; erneutes Einladen verlängert sie.')}</p><InviteHelp appUrl={appUrl}/></div></>}{item&&'project_id' in item&&<div className="workflow-inline-actions"><button className="text-button" type="button" onClick={()=>onNavigate({view:'projects',projectId:item.project_id})}>{wt(locale,'details')}<ArrowUpRight size={13}/></button><button className="text-button" type="button" onClick={()=>onNavigate({view:modal.type==='task'?'time':'tasks',projectId:item.project_id})}>{wt(locale,modal.type==='task'?'time':'tasks')}<ArrowUpRight size={13}/></button></div>}<FormActions busy={busy} onClose={onClose} label={modal.type === 'confirm' ? modal.label : modal.type === 'invite' ? t('Einladung hinterlegen') : t('Speichern')}/></form></Dialog>;
}
